{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table prd_db.beardo.dwh_Shopify_beardo_UTM_Parameters_hourly as select ShopifyQL.* ,upper(coalesce(UTM_MAPPING.CHANNEL,UTM_MAPPING_REF.CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_CHANNEL ,upper(coalesce(UTM_MAPPING.UTM_SOURCE,UTM_MAPPING_REF.UTM_SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_SOURCE from (select * from (select A.id ,A.name ,A.createdat ,coalesce(CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\" ,customerjourneysummary:\"momentsCount\") Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"content\",\'\"\',\'\') LastVisit_UTM_content ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"content\",\'\"\',\'\') FirstVisit_UTM_content ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,landingpageurl ,coalesce(Last_Moment_UTM_Source,LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source ,rank() over (partition by name order by MOMENT_ID desc) rw from datalake_db.beardo.Shopify_beardo_hourly_UTM_PARAMETERS A, lateral flatten (INPUT => customerjourney:\"moments\",OUTER => TRUE) B ) where rw=1 ) ShopifyQL left join (select * from (select *, row_number() over (partition by lower(utm_source) order by 1) rw from datalake_db.beardo.mst_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING on lower(ShopifyQL.ShopifyQL_Unmapped_Last_Source) = lower(UTM_MAPPING.utm_source) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from datalake_db.beardo.mst_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING_REF on lower(ShopifyQL.referrer_name) = lower(UTM_MAPPING_REF.utm_source) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from datalake_db.beardo.mst_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING_FIRST_CLICK on lower(ShopifyQL.FirstVisit_UTM_Source) = lower(UTM_MAPPING_FIRST_CLICK.utm_source) ; create or replace table prd_db.Beardo.dwh_GOKWIK_SOURCE_hourly as With GO_KWIK as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_source FROM datalake_db.beardo.Shopify_beardo_Hourly_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_medium FROM datalake_db.beardo.Shopify_beardo_Hourly_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_campaign FROM datalake_db.beardo.Shopify_beardo_Hourly_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_campaign\' ), utm_content_cte AS ( SELECT S.id ,UPPER(A.value:\"value\") AS utm_content FROM datalake_db.beardo.Shopify_beardo_Hourly_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_content\' ) SELECT S.id, S.tags, source_cte.utm_source AS GOKWIK_UTM_SOURCE, medium_cte.utm_medium AS GOKWIK_UTM_MEDIUM, campaign_cte.utm_campaign AS GOKWIK_UTM_CAMPAIGN, content_cte.utm_content AS GOKWIK_UTM_CONTENT FROM datalake_db.beardo.Shopify_beardo_Hourly_ORDERS S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON S.id = content_cte.id WHERE LOWER(S.note_attributes) LIKE \'%gokwik%\' ) Select GO_KWIK.* ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_MEDIUM)) as GOKWIK_MAPPED_CHANNEL ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_SOURCE)) as GOKWIK_MAPPED_SOURCE from GO_KWIK left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from datalake_db.beardo.mst_utm_mapping) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(GO_KWIK.GOKWIK_UTM_SOURCE,\'\'),ifnull(GOKWIK_UTM_MEDIUM,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) ; create or replace table prd_db.beardo.dwh_Shopify_All_orders_hourly as select AO.* ,UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.FIRSTVISIT_UTM_content) Shopifyql_FIRSTVISIT_UTM_content ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,div0(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by AO.name order by 1)) MOMENTS_COUNT ,div0(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by AO.name order by 1)) DAYSTOCONVERT ,UPPER(GOKWIK.GOKWIK_UTM_SOURCE) GOKWIK_UTM_SOURCE ,UPPER(GOKWIK.GOKWIK_UTM_MEDIUM) GOKWIK_UTM_MEDIUM ,UPPER(GOKWIK.GOKWIK_UTM_CONTENT) GOKWIK_UTM_CONTENT ,UPPER(GOKWIK.GOKWIK_MAPPED_CHANNEL) GOKWIK_MAPPED_CHANNEL ,UPPER(GOKWIK.GOKWIK_MAPPED_SOURCE) GOKWIK_MAPPED_SOURCE ,UPPER(Referrer_Name) Referrer_Name ,upper(landingpageurl) landingpageurl ,UPPER(GOKWIK.GOKWIK_UTM_CAMPAIGN) GOKWIK_UTM_CAMPAIGN ,UPPER(coalesce(GOKWIK_UTM_CAMPAIGN,LastVisit_UTM_Campaign)) FINAL_UTM_CAMPAIGN ,Upper(coalesce(GOKWIK_MAPPED_SOURCE,shopifyql_mapped_source,\'Direct\')) FINAL_UTM_SOURCE ,Upper(coalesce(GOKWIK_MAPPED_CHANNEL,shopifyql_mapped_channel,\'Direct\')) FINAL_UTM_CHANNEL ,UPPER(coalesce(ShopifyQL.LASTVISIT_UTM_content,GOKWIK.GOKWIK_UTM_CONTENT)) final_utm_content from (select * ,\'Shopify_beardo\' AS Shop_Name from datalake_db.beardo.Shopify_beardo_Hourly_ORDERS) AO left join (select * from (select *, row_number() over (partition by name order by 1) rwb from prd_db.beardo.dwh_Shopify_beardo_UTM_Parameters_hourly ) where rwb = 1 ) ShopifyQL on AO.name = ShopifyQL.name left join prd_db.Beardo.dwh_GOKWIK_SOURCE_hourly GOKWIK on AO.ID = GOKWIK.ID ; ALTER TABLE prd_db.beardo.dwh_Shopify_All_orders_hourly RENAME COLUMN _AIRBYTE_Shopify_beardo_hourly_ORDERS_HASHID to _AIRBYTE_ORDERS_HASHID; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_orders_items_discount_hourly AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:amount::FLOAT) AS DISCOUNT FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:discount_allocations AS discount_allocations FROM prd_db.beardo.dwh_Shopify_All_orders_hourly , LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.discount_allocations)B GROUP BY ORDER_ID, LINE_ITEM_ID; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_orders_items_tax_hourly AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:price::FLOAT) AS TAX, sum(B.VALUE:rate::float) as Tax_Rate FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:tax_lines AS tax_lines FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_hourly, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.tax_lines)B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_Refunds_hourly AS SELECT Name, ID AS Order_ID, Shop_name, (replace(A.value:created_at,\'\"\',\'\'))::datetime as refund_date, C.value:line_item_id AS line_item_id, SUM(C.VALUE:quantity) AS quantity, SUM(C.VALUE:subtotal) AS subtotal FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_hourly, LATERAL FLATTEN(INPUT => refunds)A, LATERAL FLATTEN(INPUT=>A.value)B, LATERAL FLATTEN(INPUT => B.value) C WHERE C.value:line_item_id IS NOT null GROUP BY Name, ID, Shop_name, A.value:created_at, C.value:line_item_id; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_orders_fulfillment_hourly AS SELECT A.value:order_id AS order_id, B.value:id Line_Item_ID, replace(A.VALUE:tracking_number,\'\"\',\'\') as AWB, Upper(replace(A.VALUE:tracking_company,\'\"\',\'\')) as Courier, Upper(replace(A.VALUE:shipment_status,\'\"\',\'\')) as Shipping_status, replace(A.VALUE:updated_at,\'\"\',\'\') as shipping_status_update_date, replace(A.VALUE:tracking_url,\'\"\',\'\') as tracking_url, replace(A.VALUE:created_at,\'\"\',\'\') as Shipping_created_at FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_hourly, LATERAL FLATTEN (INPUT => fulfillments)A,LATERAL FLATTEN (INPUT => A.value:line_items)B ; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_discount_codes_hourly AS select ID, code, affiliate from ( select ID, CODE from ( SELECT id, replace(A.value:code , \'\"\',\'\') code, row_number() over (partition by id order by code) rw FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_hourly, LATERAL FLATTEN (INPUT => discount_codes) A )where rw=1)a left join datalake_db.beardo.mst_code_affiliate_mapping b on upper(a.code) LIKE concat(\'%\',b.\"Code prefix\",\'%\') ; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Shopify_All_orders_items_hourly AS WITH CTE AS (SELECT SHOP_NAME, ID::VARCHAR(16777216) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, replace(customer:default_address:name,\'\"\',\'\') NAME, coalesce(phone, replace(customer:default_address:phone,\'\"\',\'\')) phone, coalesce(email, replace(customer:email,\'\"\',\'\')) email, replace(shipping_address:zip,\'\"\',\'\') pincode, tags, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, A.VALUE:title::STRING AS PRODUCT_NAME, CURRENCY, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'Shopify_Processed\' END AS order_status, cancelled_at::DATETIME as cancelled_at, CREATED_AT::DATETIME AS order_timestamp, A.VALUE:price::FLOAT offer_price, A.VALUE:price::FLOAT * A.VALUE:quantity::FLOAT AS LINE_ITEM_SALES, (TOTAL_SHIPPING_PRICE_SET:presentment_money:amount::FLOAT/ COUNT(ORDER_ID) OVER(PARTITION BY ORDER_ID ORDER BY ORDER_ID)) AS SHIPPING_PRICE, A.value:price/(1+A.value:tax_lines:rate), A.VALUE:quantity::FLOAT as QUANTITY, \'Shopify\' AS Source, MOMENTS_COUNT, DAYSTOCONVERT, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, FINAL_UTM_CHANNEL, FINAL_UTM_SOURCE, GOKWIK_UTM_MEDIUM, FINAL_UTM_CAMPAIGN, final_utm_content, landingpageurl, Referrer_Name, NULL as product_sub_category, payment_gateway_names, discount_codes FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_hourly, LATERAL FLATTEN (INPUT => LINE_ITEMS)A) SELECT CTE.*, dc.code discount_code, dc.affiliate, IFNULL(T.TAX_RATE,0) AS TAX_RATE, IFNULL(D.DISCOUNT,0) AS DISCOUNT, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) AS GROSS_SALES_BEFORE_TAX, IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) AS DISCOUNT_BEFORE_TAX, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) - IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) AS NET_SALES_BEFORE_TAX, case when IFNULL(T.TAX,0) = 0 then CTE.LINE_ITEM_SALES*tax_rate else IFNULL(T.TAX,0) end AS TAX, IFNULL(T.TAX,0) AS TAX_Actual, CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT,0) + CTE.SHIPPING_PRICE AS TOTAL_SALES, CASE WHEN R.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, R.total_refund_value as refund_value, R.last_refund_date as refund_date, F.AWB AWB, F.SHIPPING_STATUS Shopify_Shipping_Status, F.SHIPPING_STATUS_UPDATE_DATE Shopify_Shipping_Updated_Date, F.COURIER SHOPIFY_COURIER, coalesce(pg.mapped_pg_name,c.payment_mode) payment_gateway_mapped FROM CTE LEFT JOIN prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_ITEMS_TAX_hourly T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID LEFT JOIN prd_db.beardo.dwh_Shopify_All_orders_items_discount_hourly D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID LEFT JOIN (SELECT ORDER_ID, LINE_ITEM_ID, SUM(subtotal) as total_refund_value, SUM(quantity) as quantity, MIN(refund_date) as first_refund_date, MAX(refund_date) as last_refund_date FROM prd_db.beardo.DWH_SHOPIFY_ALL_REFUNDS_hourly GROUP BY 1, 2 ) R ON CTE.ORDER_ID = R.ORDER_ID AND CTE.LINE_ITEM_ID = R.LINE_ITEM_ID LEFT JOIN prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_FULFILLMENT_hourly F ON CTE.ORDER_ID = F.ORDER_ID AND CTE.LINE_ITEM_ID = F.LINE_ITEM_ID left join (select * from( select *, row_number() over (partition by id, code order by 1) rw from prd_db.beardo.dwh_Shopify_All_discount_codes_hourly) where rw = 1) DC on CTE.order_id = DC.id left join (select * from datalake_db.beardo.mst_payment_gateway_names_mapping qualify row_number() over(partition by lower(replace(shopify_pg_name::string,\' \',\'\')) order by 1) = 1 )pg on lower(replace(pg.shopify_pg_name::string,\' \',\'\')) = lower(replace(cte.payment_gateway_names::string,\' \',\'\')) left join ( select reference_code,payment_mode from prd_db.beardo.dwh_unicommerce_fact_items qualify row_number()over(partition by reference_code order by last_update_date) = 1 and lower(marketplace) like \'%shopify%\' ) c on lower(replace(cte.order_name,\'#\',\'\')) = lower(replace(c.reference_code,\'#\',\'\')) ; CREATE OR REPLACE TABLE prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS_hourly AS SELECT O.SHOP_NAME, O.ORDER_ID, O.ORDER_NAME, O.CUSTOMER:id::int AS customer_id, O.Name, O.EMAIL, o.pincode, O.PHONE, O.Tags, O.LINE_ITEM_ID, O.SKU, O.PRODUCT_ID, O.cancelled_at, O.refund_date, O.refund_value, O.CURRENCY, O.IS_REFUND, CASE WHEN CD.city IS NULL OR CD.city = \'\' THEN \'NA\' ELSE upper(CD.city) END AS city, CASE WHEN CD.province IS NULL OR CD.province = \'\' THEN \'NA\' ELSE upper(CD.province) END AS state, CASE WHEN P.title = \'\' THEN \'NA\' ELSE P.title END AS product_name, CASE WHEN P.product_type = \'\' THEN \'NA\' ELSE P.product_type END AS category, O.order_status, O.order_timestamp, offer_price, O.LINE_ITEM_SALES, O.SHIPPING_PRICE, O.QUANTITY, O.TAX, O.TAX_Actual, O.TAX_RATE, O.DISCOUNT, O.DISCOUNT_BEFORE_TAX, O.GROSS_SALES_AFTER_TAX, O.GROSS_SALES_BEFORE_TAX, O.NET_SALES_BEFORE_TAX, O.TOTAL_SALES, O.Source, O.MOMENTS_COUNT, O.DAYSTOCONVERT, O.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, O.SHOPIFYQL_MAPPED_CHANNEL, O.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, O.Shopifyql_LAST_VISIT_NON_UTM_SOURCE, O.Shopifyql_FIRSTVISIT_UTM_MEDIUM, O.Shopifyql_LAST_MOMENT_UTM_MEDIUM, O.FINAL_UTM_CHANNEL, O.FINAL_UTM_CAMPAIGN, O.GOKWIK_UTM_MEDIUM, O.FINAL_UTM_SOURCE, o.final_utm_content, O.landingpageurl, O.Referrer_Name, O.AWB, O.SHOPIFY_SHIPPING_STATUS, O.SHOPIFY_SHIPPING_UPDATED_DATE, O.SHOPIFY_COURIER, O.Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, O.Shopifyql_LAST_VISIT_UTM_CAMPAIGN, o.product_sub_category, o.discount_code, o.affiliate, payment_gateway_mapped FROM prd_db.beardo.DWH_SHOPIFY_ALL_ORDERS_ITEMS_hourly O LEFT JOIN prd_db.beardo.dwh_Shopify_All_products P ON O.PRODUCT_ID = P.id LEFT JOIN(SELECT customer_id, city, province, row_number() OVER ( partition BY customer_id ORDER BY id DESC) rowid FROM prd_db.beardo.dwh_Shopify_All_customers_addresses) AS CD ON O.CUSTOMER:id::int = CD.customer_id AND CD.rowid = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            